#include <cmath>
#include <format>
#include <iostream>
#include <string_view>
#include <vector>

// The arithmetic the bench predicts its stop with: the supervisor notices nothing for the
// odometry timeout plus one tick of its 20 Hz loop, and the robot then decelerates at the
// vehicle's braking limit.
struct Inputs {
  double speed_mps;     // what the follower was driving at
  double detect_s;      // odometry timeout plus one supervisor tick
  double brake_mps2;    // the vehicle's deceleration limit
};

[[nodiscard]] double stop_distance_m(Inputs in) {
  return in.speed_mps * in.detect_s + in.speed_mps * in.speed_mps / (2.0 * in.brake_mps2);
}

[[nodiscard]] double stop_time_s(Inputs in) { return in.detect_s + in.speed_mps / in.brake_mps2; }

// How far this input has to move, as a multiple of itself, before the stop distance reaches the
// scenario's creep limit. Found by bisection, so the model needs no algebra to be swept.
[[nodiscard]] double breaking_multiple(Inputs nominal, int which, double limit_m) {
  const auto with = [nominal, which](double factor) {
    Inputs changed = nominal;
    if (which == 0) changed.speed_mps *= factor;
    if (which == 1) changed.detect_s *= factor;
    if (which == 2) changed.brake_mps2 *= factor;
    return changed;
  };
  const bool grows = which != 2;  // a weaker brake means a smaller factor, not a larger one
  double lo = grows ? 1.0 : 0.0001;
  double hi = grows ? 1000.0 : 1.0;
  for (int step = 0; step < 200; ++step) {
    const double mid = 0.5 * (lo + hi);
    if ((stop_distance_m(with(mid)) < limit_m) == grows) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  return 0.5 * (lo + hi);
}

struct Row {
  std::string_view name;
  int which;
};

int main() {
  constexpr Inputs nominal{.speed_mps = 0.20, .detect_s = 0.30, .brake_mps2 = 1.0};
  constexpr double creep_limit_m = 0.25;   // the scenario's limit on how far it may creep
  constexpr double rest_limit_s = 1.50;    // and on how long it may take to come to rest

  std::cout << std::format("nominal: {:.3f} m of creep and {:.2f} s to rest, against limits of {:.2f} m and {:.2f} s\n\n",
                           stop_distance_m(nominal), stop_time_s(nominal), creep_limit_m, rest_limit_s);

  std::cout << std::format("{:<14} {:>10} {:>10} {:>12} {:>16}\n", "input -20/+20%", "creep low", "creep high",
                           "elasticity", "limit reached at");
  for (const Row& row : std::vector<Row>{{.name = "drive speed", .which = 0},
                                         {.name = "detect time", .which = 1},
                                         {.name = "brake limit", .which = 2}}) {
    const auto with = [&row, nominal](double factor) {
      Inputs changed = nominal;
      if (row.which == 0) changed.speed_mps *= factor;
      if (row.which == 1) changed.detect_s *= factor;
      if (row.which == 2) changed.brake_mps2 *= factor;
      return changed;
    };
    const double low = stop_distance_m(with(0.8));
    const double high = stop_distance_m(with(1.2));
    const double base = stop_distance_m(nominal);
    const double elasticity = ((high - low) / base) / 0.4;  // percent out per percent in
    std::cout << std::format("{:<14} {:>9.4f}m {:>9.4f}m {:>12.2f} {:>15.2f}x\n", row.name, low, high, elasticity,
                             breaking_multiple(nominal, row.which, creep_limit_m));
  }
}
